CREATE OR REPLACE FUNCTION public.normalize_contract_payment_schedule_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF lower(COALESCE(NEW.status, '')) = 'partial' THEN
    NEW.status := 'partially_paid';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.preserve_inactive_duplicate_schedule_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_inactive boolean := lower(coalesce(OLD.status, '')) IN (
    'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
  );
  v_new_active boolean := lower(coalesce(NEW.status, '')) NOT IN (
    'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
  );
BEGIN
  IF v_old_inactive
     AND v_new_active
     AND EXISTS (
       SELECT 1
       FROM public.contract_payment_schedules other_schedule
       WHERE other_schedule.id <> OLD.id
         AND other_schedule.company_id = OLD.company_id
         AND other_schedule.contract_id = OLD.contract_id
         AND other_schedule.due_date IS NOT DISTINCT FROM OLD.due_date
         AND lower(coalesce(other_schedule.status, '')) NOT IN (
           'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
         )
     )
  THEN
    NEW.status := OLD.status;
    NEW.invoice_id := OLD.invoice_id;
    NEW.paid_amount := OLD.paid_amount;
    NEW.paid_date := OLD.paid_date;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_payment_schedule_first_of_month()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- تحديث due_date ليكون أول يوم في الشهر
    IF NEW.due_date IS NOT NULL THEN
        NEW.due_date := DATE_TRUNC('month', NEW.due_date)::DATE;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_invoice_financial_controls()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_paid numeric := 0;
BEGIN
  IF public.financial_controls_bypass_enabled() THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM public.assert_financial_period_is_open(NEW.company_id, NEW.invoice_date);
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.total_amount IS DISTINCT FROM OLD.total_amount THEN
    v_paid := public.canonical_invoice_paid_amount(OLD.id, NULL);
    IF COALESCE(NEW.total_amount, 0) + 0.01 < v_paid THEN
      RAISE EXCEPTION 'Invoice total cannot be lower than its allocated receipts (QAR %)', v_paid
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE'
     AND (NEW.company_id IS DISTINCT FROM OLD.company_id
       OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.contract_id IS DISTINCT FROM OLD.contract_id)
     AND EXISTS (
       SELECT 1 FROM public.payment_allocations allocation
       WHERE allocation.allocation_type = 'invoice'
         AND allocation.target_id = OLD.id
         AND allocation.is_active = true
     )
  THEN
    RAISE EXCEPTION 'Invoice ownership cannot change while active payment allocations exist'
      USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'DELETE'
     AND (
       COALESCE(OLD.paid_amount, 0) > 0
       OR EXISTS (
         SELECT 1 FROM public.payments payment
         WHERE payment.invoice_id = OLD.id
           AND lower(COALESCE(payment.payment_status, '')) IN ('completed', 'paid', 'success', 'succeeded')
       )
       OR EXISTS (
         SELECT 1 FROM public.payment_allocations allocation
         WHERE allocation.allocation_type = 'invoice'
           AND allocation.target_id = OLD.id
           AND allocation.is_active = true
       )
       OR OLD.journal_entry_id IS NOT NULL
     )
  THEN
    RAISE EXCEPTION 'Invoices with payments, allocations, or journals cannot be deleted'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.log_activity_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_id_val uuid;
    company_id_val uuid;
    action_name text;
    resource_name text;
    old_data jsonb;
    new_data jsonb;
BEGIN
    -- تحديد المستخدم الحالي
    user_id_val := auth.uid();

    -- تحديد معرف الشركة
    IF TG_TABLE_NAME = 'companies' THEN
        company_id_val := COALESCE(NEW.id, OLD.id);
    ELSE
        company_id_val := COALESCE(NEW.company_id, OLD.company_id);
    END IF;

    -- تحديد نوع العملية
    CASE TG_OP
        WHEN 'INSERT' THEN
            action_name := 'create';
            new_data := row_to_json(NEW)::jsonb;
        WHEN 'UPDATE' THEN
            action_name := 'update';
            old_data := row_to_json(OLD)::jsonb;
            new_data := row_to_json(NEW)::jsonb;
        WHEN 'DELETE' THEN
            action_name := 'delete';
            old_data := row_to_json(OLD)::jsonb;
        ELSE
            action_name := 'unknown';
    END CASE;

    -- تحديد اسم المورد
    resource_name := TG_TABLE_NAME;

    -- إدراج السجل
    INSERT INTO public.system_logs (
        company_id,
        user_id,
        level,
        category,
        action,
        resource_type,
        resource_id,
        message,
        metadata
    ) VALUES (
        company_id_val,
        user_id_val,
        'info',
        CASE TG_TABLE_NAME
            WHEN 'customers' THEN 'customers'
            WHEN 'contracts' THEN 'contracts'
            WHEN 'vehicles' THEN 'fleet'
            WHEN 'employees' THEN 'hr'
            WHEN 'invoices' THEN 'finance'
            WHEN 'payments' THEN 'finance'
            WHEN 'bank_transactions' THEN 'finance'
            WHEN 'journal_entries' THEN 'finance'
            ELSE 'system'
        END,
        action_name,
        resource_name,
        COALESCE(NEW.id, OLD.id),
        CASE TG_OP
            WHEN 'INSERT' THEN 'تم إنشاء ' || resource_name || ' جديد'
            WHEN 'UPDATE' THEN 'تم تحديث ' || resource_name
            WHEN 'DELETE' THEN 'تم حذف ' || resource_name
        END,
        jsonb_build_object(
            'operation', TG_OP,
            'table', TG_TABLE_NAME,
            'old_data', old_data,
            'new_data', new_data
        )
    );

    RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_invoice_payment_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total numeric := COALESCE(NEW.total_amount, 0);
  v_paid numeric := COALESCE(NEW.paid_amount, 0);
  v_balance numeric := GREATEST(v_total - v_paid, 0);
  v_status text := LOWER(COALESCE(NEW.status, ''));
  v_payment_status text := LOWER(COALESCE(NEW.payment_status, ''));
BEGIN
  IF v_status = 'cancelled' OR v_payment_status = 'cancelled' THEN
    RETURN NEW;
  END IF;

  NEW.balance_due := v_balance;

  IF v_total <= 0 THEN
    RETURN NEW;
  END IF;

  IF v_paid <= 0 THEN
    NEW.payment_status := 'unpaid';
    IF LOWER(COALESCE(NEW.status, '')) = 'paid' THEN
      NEW.status := CASE
        WHEN NEW.due_date IS NOT NULL AND NEW.due_date < CURRENT_DATE THEN 'overdue'
        ELSE 'sent'
      END;
    END IF;
  ELSIF v_total - v_paid <= 0.01 THEN
    NEW.payment_status := 'paid';
    NEW.status := 'paid';
    NEW.balance_due := 0;
  ELSE
    NEW.payment_status := 'partial';
    IF LOWER(COALESCE(NEW.status, '')) = 'paid' THEN
      NEW.status := CASE
        WHEN NEW.due_date IS NOT NULL AND NEW.due_date < CURRENT_DATE THEN 'overdue'
        ELSE 'sent'
      END;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.financial_audit_trigger_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_company_id uuid;
  v_resource_id uuid;
  v_resource_type text;
  v_details jsonb;
  v_severity text := 'low';
  v_status text := 'success';
  v_old_row jsonb := NULL;
  v_new_row jsonb := NULL;
  v_user_id uuid := auth.uid();
BEGIN
  v_resource_type := TG_TABLE_NAME;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_old_row := to_jsonb(OLD);
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_new_row := to_jsonb(NEW);
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_action := v_resource_type || '_created';
    v_company_id := NEW.company_id;
    v_resource_id := NEW.id;
    v_details := jsonb_build_object('new_values', v_new_row);
    IF TG_TABLE_NAME = 'payments' THEN
      v_severity := 'medium';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := v_resource_type || '_updated';
    v_company_id := NEW.company_id;
    v_resource_id := NEW.id;
    v_details := jsonb_build_object(
      'old_values', v_old_row,
      'new_values', v_new_row,
      'changed_fields', (
        SELECT jsonb_object_agg(key, value)
        FROM jsonb_each(v_new_row) AS n
        WHERE n.value IS DISTINCT FROM (v_old_row -> n.key)
      )
    );

    IF TG_TABLE_NAME = 'payments'
       AND (v_old_row ->> 'payment_status') IS DISTINCT FROM (v_new_row ->> 'payment_status')
    THEN
      v_severity := 'high';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := v_resource_type || '_deleted';
    v_company_id := OLD.company_id;
    v_resource_id := OLD.id;
    v_details := jsonb_build_object('old_values', v_old_row);
    v_severity := 'critical';
  END IF;

  v_user_id := COALESCE(
    NULLIF(v_new_row ->> 'created_by', '')::uuid,
    NULLIF(v_old_row ->> 'created_by', '')::uuid,
    auth.uid()
  );

  INSERT INTO public.audit_logs (
    action,
    severity,
    company_id,
    resource_type,
    resource_id,
    old_values,
    new_values,
    metadata,
    status,
    user_id
  )
  VALUES (
    v_action,
    v_severity,
    v_company_id,
    v_resource_type,
    v_resource_id,
    CASE WHEN v_details ? 'old_values' THEN v_details -> 'old_values' ELSE NULL END,
    CASE WHEN v_details ? 'new_values' THEN v_details -> 'new_values' ELSE NULL END,
    CASE WHEN v_details ? 'changed_fields' THEN v_details -> 'changed_fields' ELSE NULL END,
    v_status,
    v_user_id
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_invoice_date_first_of_month()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.due_date := pg_catalog.date_trunc(
    'month',
    COALESCE(NEW.invoice_month, NEW.invoice_date)::timestamp
  )::date;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_invoice_balance_due()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF lower(COALESCE(NEW.status, '')) IN (
       'cancelled', 'canceled', 'void', 'voided', 'deleted'
     )
     OR lower(COALESCE(NEW.payment_status, '')) IN (
       'cancelled', 'canceled', 'void', 'voided', 'deleted'
     )
  THEN
    NEW.balance_due := 0;
    RETURN NEW;
  END IF;

  IF (NEW.balance_due IS NULL OR NEW.balance_due = 0)
     AND COALESCE(NEW.paid_amount, 0) = 0
  THEN
    NEW.balance_due := NEW.total_amount;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_invoice_journal_entry_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_number text;
  v_journal_id uuid;
  v_ar_account_id uuid;
  v_revenue_account_id uuid;
  v_tax_account_id uuid;
BEGIN
  IF NEW.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_journal_id
  FROM public.journal_entries
  WHERE company_id = NEW.company_id
    AND reference_type = 'invoice'
    AND reference_id = NEW.id
  ORDER BY created_at ASC NULLS LAST
  LIMIT 1;

  IF v_journal_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT am.chart_of_accounts_id INTO v_ar_account_id
  FROM public.account_mappings am
  JOIN public.default_account_types dat ON am.default_account_type_id = dat.id
  WHERE am.company_id = NEW.company_id
    AND dat.type_code = 'RECEIVABLES'
    AND am.is_active = true
  LIMIT 1;

  SELECT am.chart_of_accounts_id INTO v_revenue_account_id
  FROM public.account_mappings am
  JOIN public.default_account_types dat ON am.default_account_type_id = dat.id
  WHERE am.company_id = NEW.company_id
    AND dat.type_code IN ('RENTAL_REVENUE', 'SALES_REVENUE', 'REVENUE')
    AND am.is_active = true
  ORDER BY
    CASE dat.type_code
      WHEN 'RENTAL_REVENUE' THEN 1
      WHEN 'SALES_REVENUE' THEN 2
      WHEN 'REVENUE' THEN 3
      ELSE 4
    END
  LIMIT 1;

  IF v_ar_account_id IS NULL OR v_revenue_account_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_entry_number := 'INV-' || to_char(COALESCE(NEW.invoice_date, CURRENT_DATE), 'YYYYMMDD') || '-' || substring(NEW.id::text, 1, 8);

  INSERT INTO public.journal_entries (
    company_id, entry_number, entry_date, description,
    total_debit, total_credit, status, reference_type, reference_id, created_by
  )
  VALUES (
    NEW.company_id, v_entry_number,
    COALESCE(NEW.invoice_date, CURRENT_DATE),
    'Invoice: ' || COALESCE(NEW.invoice_number, NEW.id::text),
    NEW.total_amount, NEW.total_amount, 'draft', 'invoice', NEW.id, NEW.created_by
  )
  RETURNING id INTO v_journal_id;

  INSERT INTO public.journal_entry_lines (journal_entry_id, account_id, line_number, line_description, debit_amount, credit_amount)
  VALUES
    (v_journal_id, v_ar_account_id, 1, 'Customer receivable', NEW.total_amount, 0),
    (v_journal_id, v_revenue_account_id, 2, 'Service revenue', 0, COALESCE(NEW.subtotal, NEW.total_amount - COALESCE(NEW.tax_amount, 0)));

  IF COALESCE(NEW.tax_amount, 0) > 0 THEN
    SELECT am.chart_of_accounts_id INTO v_tax_account_id
    FROM public.account_mappings am
    JOIN public.default_account_types dat ON am.default_account_type_id = dat.id
    WHERE am.company_id = NEW.company_id
      AND dat.type_code IN ('TAX_PAYABLE', 'VAT_PAYABLE', 'TAX')
      AND am.is_active = true
    LIMIT 1;

    IF v_tax_account_id IS NOT NULL THEN
      INSERT INTO public.journal_entry_lines (journal_entry_id, account_id, line_number, line_description, debit_amount, credit_amount)
      VALUES (v_journal_id, v_tax_account_id, 3, 'Collected tax', 0, NEW.tax_amount);
    END IF;
  END IF;

  UPDATE public.journal_entries
  SET status = 'posted', posted_by = NEW.created_by, posted_at = now(), updated_at = now()
  WHERE id = v_journal_id;

  NEW.journal_entry_id := v_journal_id;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_invoice_month()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- يحترم invoice_month الصريح (شهر الفوترة) وإلا يشتقه من invoice_date
    NEW.invoice_month := COALESCE(
        NEW.invoice_month,
        DATE_TRUNC('month', NEW.invoice_date)::DATE
    );
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_duplicate_monthly_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_invoice_month date;
  v_existing_invoice_number text;
BEGIN
  IF NEW.penalty_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.contract_id IS NULL
     OR COALESCE(NEW.invoice_month, NEW.invoice_date) IS NULL
     OR lower(COALESCE(NEW.status, '')) IN (
       'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
     )
     OR lower(COALESCE(NEW.payment_status, '')) IN (
       'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
     )
  THEN
    RETURN NEW;
  END IF;

  v_invoice_month := date_trunc(
    'month',
    COALESCE(NEW.invoice_month, NEW.invoice_date)::timestamp without time zone
  )::date;

  SELECT invoice.invoice_number
  INTO v_existing_invoice_number
  FROM public.invoices invoice
  WHERE invoice.company_id = NEW.company_id
    AND invoice.contract_id = NEW.contract_id
    AND invoice.penalty_id IS NULL
    AND date_trunc(
      'month',
      COALESCE(invoice.invoice_month, invoice.invoice_date)::timestamp without time zone
    )::date = v_invoice_month
    AND lower(COALESCE(invoice.status, '')) NOT IN (
      'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
    )
    AND lower(COALESCE(invoice.payment_status, '')) NOT IN (
      'cancelled', 'canceled', 'void', 'voided', 'deleted', 'inactive'
    )
    AND invoice.id <> COALESCE(
      NEW.id,
      '00000000-0000-0000-0000-000000000000'::uuid
    )
  ORDER BY invoice.id
  LIMIT 1;

  IF v_existing_invoice_number IS NOT NULL THEN
    RAISE EXCEPTION
      'An active invoice (%) already exists for this contract canonical month %',
      v_existing_invoice_number,
      to_char(v_invoice_month, 'YYYY-MM')
      USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_invoice_date_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_contract_start_date date;
BEGIN
  IF NEW.contract_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT start_date INTO v_contract_start_date
  FROM public.contracts
  WHERE id = NEW.contract_id;

  IF v_contract_start_date IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.contract_id IS NOT DISTINCT FROM OLD.contract_id
      AND NEW.invoice_date IS NOT DISTINCT FROM OLD.invoice_date
      AND NEW.due_date IS NOT DISTINCT FROM OLD.due_date THEN
      RETURN NEW;
    END IF;
  END IF;

  -- Only block if invoice_date month is BEFORE contract start month (allow same month)
  IF NEW.invoice_date IS NOT NULL AND DATE_TRUNC('month', NEW.invoice_date) < DATE_TRUNC('month', v_contract_start_date) THEN
    RAISE EXCEPTION 'Invoice date (%) cannot be before contract start date (%)',
      NEW.invoice_date, v_contract_start_date;
  END IF;

  IF NEW.due_date IS NOT NULL AND DATE_TRUNC('month', NEW.due_date) < DATE_TRUNC('month', v_contract_start_date) THEN
    RAISE EXCEPTION 'Invoice due date (%) cannot be before contract start date (%)',
      NEW.due_date, v_contract_start_date;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.persist_invoice_reference_journal_link_before_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_journal_id uuid;
  v_journal_count integer;
BEGIN
  IF NEW.journal_entry_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT
    (array_agg(entry.id ORDER BY entry.id))[1],
    count(*)
  INTO v_journal_id, v_journal_count
  FROM public.journal_entries entry
  WHERE entry.company_id = NEW.company_id
    AND entry.reference_type = 'invoice'
    AND entry.reference_id = NEW.id;

  IF v_journal_count > 1 THEN
    RAISE EXCEPTION 'Invoice % has multiple reference journals', NEW.id
      USING ERRCODE = 'P0001';
  END IF;
  IF v_journal_count = 1 THEN
    NEW.journal_entry_id := v_journal_id;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.after_payment_allocation_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_contract_id uuid;
BEGIN
  IF COALESCE(current_setting('app.payment_allocation_batch_mode', true), '') = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    PERFORM public.sync_payment_allocation_state(OLD.payment_id);
    IF OLD.allocation_type = 'invoice' THEN
      PERFORM public.recalculate_invoice_financial_state(OLD.target_id);
      SELECT invoice.contract_id
      INTO v_contract_id
      FROM public.invoices invoice
      WHERE invoice.id = OLD.target_id;
      PERFORM public.recalculate_contract_financial_state(v_contract_id);
    END IF;
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    PERFORM public.sync_payment_allocation_state(NEW.payment_id);
    IF NEW.allocation_type = 'invoice' THEN
      PERFORM public.recalculate_invoice_financial_state(NEW.target_id);
      SELECT invoice.contract_id
      INTO v_contract_id
      FROM public.invoices invoice
      WHERE invoice.id = NEW.target_id;
      PERFORM public.recalculate_contract_financial_state(v_contract_id);
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_payment_allocation_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_payment_company_id uuid;
  v_payment_contract_id uuid;
  v_payment_customer_id uuid;
  v_invoice_company_id uuid;
  v_invoice_contract_id uuid;
  v_invoice_customer_id uuid;
BEGIN
  IF NEW.is_active IS DISTINCT FROM true
     OR NEW.allocation_type IS DISTINCT FROM 'invoice' THEN
    RETURN NEW;
  END IF;

  SELECT payment.company_id, payment.contract_id, payment.customer_id
  INTO v_payment_company_id, v_payment_contract_id, v_payment_customer_id
  FROM public.payments payment
  WHERE payment.id = NEW.payment_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Allocation payment does not exist (%)', NEW.payment_id
      USING ERRCODE = '23503';
  END IF;

  SELECT invoice.company_id, invoice.contract_id, invoice.customer_id
  INTO v_invoice_company_id, v_invoice_contract_id, v_invoice_customer_id
  FROM public.invoices invoice
  WHERE invoice.id = NEW.target_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Allocation invoice does not exist (%)', NEW.target_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.company_id IS DISTINCT FROM v_payment_company_id
     OR NEW.company_id IS DISTINCT FROM v_invoice_company_id THEN
    RAISE EXCEPTION 'Allocation, payment, and invoice must belong to the same company'
      USING ERRCODE = '23514';
  END IF;

  IF v_payment_contract_id IS NOT NULL
     AND v_invoice_contract_id IS NOT NULL
     AND v_payment_contract_id IS DISTINCT FROM v_invoice_contract_id THEN
    RAISE EXCEPTION 'Allocated payment contract does not match invoice contract'
      USING ERRCODE = '23514';
  END IF;

  IF v_payment_customer_id IS NOT NULL
     AND v_invoice_customer_id IS NOT NULL
     AND v_payment_customer_id IS DISTINCT FROM v_invoice_customer_id THEN
    RAISE EXCEPTION 'Allocated payment customer does not match invoice customer'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_payment_allocation_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment public.payments%ROWTYPE;
  v_invoice public.invoices%ROWTYPE;
  v_late_fee public.late_fees%ROWTYPE;
  v_payment_allocated numeric := 0;
  v_target_allocated numeric := 0;
BEGIN
  IF TG_OP = 'UPDATE' AND (
    NEW.company_id IS DISTINCT FROM OLD.company_id
    OR NEW.payment_id IS DISTINCT FROM OLD.payment_id
    OR NEW.allocation_type IS DISTINCT FROM OLD.allocation_type
    OR NEW.target_id IS DISTINCT FROM OLD.target_id
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Allocation ownership and target fields are immutable; void and replace the row'
      USING ERRCODE = 'P0001';
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.is_active = true AND NEW.is_active = false THEN
    NEW.voided_at := COALESCE(NEW.voided_at, now());
    IF NULLIF(BTRIM(COALESCE(NEW.void_reason, '')), '') IS NULL THEN
      RAISE EXCEPTION 'A void reason is required for payment allocations'
        USING ERRCODE = 'P0001';
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
  END IF;

  IF NEW.is_active = false THEN
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF NEW.allocation_type NOT IN ('invoice', 'late_fee') THEN
    RAISE EXCEPTION 'Only invoice and late-fee allocations are currently supported'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT *
  INTO v_payment
  FROM public.payments payment
  WHERE payment.id = NEW.payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment not found for allocation' USING ERRCODE = 'P0001';
  END IF;
  IF v_payment.company_id IS DISTINCT FROM NEW.company_id THEN
    RAISE EXCEPTION 'Allocation company does not match payment company'
      USING ERRCODE = 'P0001';
  END IF;
  IF lower(COALESCE(v_payment.payment_status, '')) NOT IN ('completed', 'paid', 'success', 'succeeded')
     OR lower(COALESCE(v_payment.transaction_type::text, 'receipt')) <> 'receipt'
  THEN
    RAISE EXCEPTION 'Only completed receipt payments can be allocated'
      USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(SUM(allocation.amount), 0)
  INTO v_payment_allocated
  FROM public.payment_allocations allocation
  WHERE allocation.payment_id = NEW.payment_id
    AND allocation.is_active = true
    AND allocation.id IS DISTINCT FROM NEW.id;

  IF v_payment_allocated + NEW.amount > COALESCE(v_payment.amount, 0) + 0.01 THEN
    RAISE EXCEPTION 'Allocation would exceed payment amount by QAR %',
      round((v_payment_allocated + NEW.amount - COALESCE(v_payment.amount, 0))::numeric, 2)
      USING ERRCODE = 'P0001';
  END IF;

  IF NEW.allocation_type = 'invoice' THEN
    SELECT *
    INTO v_invoice
    FROM public.invoices invoice
    WHERE invoice.id = NEW.target_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Target invoice not found' USING ERRCODE = 'P0001';
    END IF;
    IF v_invoice.company_id IS DISTINCT FROM NEW.company_id
       OR (v_invoice.customer_id IS NOT NULL AND v_invoice.customer_id IS DISTINCT FROM v_payment.customer_id)
       OR v_invoice.contract_id IS DISTINCT FROM v_payment.contract_id
    THEN
      RAISE EXCEPTION 'Allocation invoice does not match payment company, customer, or contract'
        USING ERRCODE = 'P0001';
    END IF;
    IF lower(COALESCE(v_invoice.status, '')) IN ('cancelled', 'canceled', 'void', 'voided', 'deleted')
       OR lower(COALESCE(v_invoice.payment_status, '')) IN ('cancelled', 'canceled', 'void', 'voided')
    THEN
      RAISE EXCEPTION 'Inactive invoices cannot receive allocations' USING ERRCODE = 'P0001';
    END IF;

    v_target_allocated := public.canonical_invoice_paid_amount(NEW.target_id, NEW.payment_id);
    SELECT v_target_allocated + COALESCE(SUM(allocation.amount), 0)
    INTO v_target_allocated
    FROM public.payment_allocations allocation
    WHERE allocation.payment_id = NEW.payment_id
      AND allocation.allocation_type = 'invoice'
      AND allocation.target_id = NEW.target_id
      AND allocation.is_active = true
      AND allocation.id IS DISTINCT FROM NEW.id;

    IF v_target_allocated + NEW.amount > COALESCE(v_invoice.total_amount, 0) + 0.01 THEN
      RAISE EXCEPTION 'Allocation would overpay invoice by QAR %',
        round((v_target_allocated + NEW.amount - COALESCE(v_invoice.total_amount, 0))::numeric, 2)
        USING ERRCODE = 'P0001';
    END IF;
  ELSE
    SELECT *
    INTO v_late_fee
    FROM public.late_fees late_fee
    WHERE late_fee.id = NEW.target_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Target late fee not found' USING ERRCODE = 'P0001';
    END IF;
    IF v_late_fee.company_id IS DISTINCT FROM NEW.company_id
       OR v_late_fee.invoice_id IS DISTINCT FROM v_payment.invoice_id
       OR v_late_fee.contract_id IS DISTINCT FROM v_payment.contract_id
       OR lower(COALESCE(v_late_fee.status, '')) IN ('waived', 'cancelled')
    THEN
      RAISE EXCEPTION 'Late-fee allocation does not match the payment or targets an inactive fee'
        USING ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(SUM(allocation.amount), 0)
    INTO v_target_allocated
    FROM public.payment_allocations allocation
    JOIN public.payments payment ON payment.id = allocation.payment_id
    WHERE allocation.allocation_type = 'late_fee'
      AND allocation.target_id = NEW.target_id
      AND allocation.is_active = true
      AND allocation.id IS DISTINCT FROM NEW.id
      AND lower(COALESCE(payment.payment_status, '')) IN ('completed', 'paid', 'success', 'succeeded');

    IF v_target_allocated + NEW.amount > COALESCE(v_late_fee.fee_amount, 0) + 0.01 THEN
      RAISE EXCEPTION 'Allocation would overpay late fee by QAR %',
        round((v_target_allocated + NEW.amount - COALESCE(v_late_fee.fee_amount, 0))::numeric, 2)
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_contract_payment_totals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_contract RECORD;
    v_total_paid NUMERIC;
    v_balance_due NUMERIC;
BEGIN
    -- Only process payments linked to contracts
    IF NEW.contract_id IS NULL THEN
        -- For DELETE, check OLD
        IF TG_OP = 'DELETE' AND OLD.contract_id IS NOT NULL THEN
            -- Continue with OLD contract_id
        ELSE
            IF TG_OP = 'DELETE' THEN
                RETURN OLD;
            ELSE
                RETURN NEW;
            END IF;
        END IF;
    END IF;

    -- Determine which contract_id and company_id to use
    DECLARE
        v_contract_id_to_use UUID := COALESCE(NEW.contract_id, OLD.contract_id);
        v_company_id_to_use UUID := COALESCE(NEW.company_id, OLD.company_id);
    BEGIN
        -- Get contract details
        SELECT * INTO v_contract
        FROM contracts
        WHERE id = v_contract_id_to_use;

        IF NOT FOUND THEN
            IF TG_OP = 'DELETE' THEN
                RETURN OLD;
            ELSE
                RETURN NEW;
            END IF;
        END IF;

        -- Calculate total paid for this contract
        SELECT COALESCE(SUM(amount), 0)
        INTO v_total_paid
        FROM payments
        WHERE contract_id = v_contract_id_to_use
          AND payment_status = 'completed'
          AND company_id = v_company_id_to_use;

        v_balance_due := COALESCE(v_contract.contract_amount, 0) - v_total_paid;

        -- Update contract
        UPDATE contracts
        SET
            total_paid = v_total_paid,
            balance_due = v_balance_due,
            updated_at = NOW()
        WHERE id = v_contract_id_to_use;

        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        ELSE
            RETURN NEW;
        END IF;
    END;
END;
$function$

