CREATE OR REPLACE FUNCTION public.log_activity_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_id_val uuid;
    company_id_val uuid;
    action_name text;
    resource_name text;
    old_data jsonb;
    new_data jsonb;
BEGIN
    -- تحديد المستخدم الحالي
    user_id_val := auth.uid();

    -- تحديد معرف الشركة
    IF TG_TABLE_NAME = 'companies' THEN
        company_id_val := COALESCE(NEW.id, OLD.id);
    ELSE
        company_id_val := COALESCE(NEW.company_id, OLD.company_id);
    END IF;

    -- تحديد نوع العملية
    CASE TG_OP
        WHEN 'INSERT' THEN
            action_name := 'create';
            new_data := row_to_json(NEW)::jsonb;
        WHEN 'UPDATE' THEN
            action_name := 'update';
            old_data := row_to_json(OLD)::jsonb;
            new_data := row_to_json(NEW)::jsonb;
        WHEN 'DELETE' THEN
            action_name := 'delete';
            old_data := row_to_json(OLD)::jsonb;
        ELSE
            action_name := 'unknown';
    END CASE;

    -- تحديد اسم المورد
    resource_name := TG_TABLE_NAME;

    -- إدراج السجل
    INSERT INTO public.system_logs (
        company_id,
        user_id,
        level,
        category,
        action,
        resource_type,
        resource_id,
        message,
        metadata
    ) VALUES (
        company_id_val,
        user_id_val,
        'info',
        CASE TG_TABLE_NAME
            WHEN 'customers' THEN 'customers'
            WHEN 'contracts' THEN 'contracts'
            WHEN 'vehicles' THEN 'fleet'
            WHEN 'employees' THEN 'hr'
            WHEN 'invoices' THEN 'finance'
            WHEN 'payments' THEN 'finance'
            WHEN 'bank_transactions' THEN 'finance'
            WHEN 'journal_entries' THEN 'finance'
            ELSE 'system'
        END,
        action_name,
        resource_name,
        COALESCE(NEW.id, OLD.id),
        CASE TG_OP
            WHEN 'INSERT' THEN 'تم إنشاء ' || resource_name || ' جديد'
            WHEN 'UPDATE' THEN 'تم تحديث ' || resource_name
            WHEN 'DELETE' THEN 'تم حذف ' || resource_name
        END,
        jsonb_build_object(
            'operation', TG_OP,
            'table', TG_TABLE_NAME,
            'old_data', old_data,
            'new_data', new_data
        )
    );

    RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_payment_financial_integration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Generate payment number if missing
    IF NEW.payment_number IS NULL OR NEW.payment_number = '' THEN
        BEGIN
            NEW.payment_number := generate_payment_number(NEW.company_id);
        EXCEPTION WHEN OTHERS THEN
            NEW.payment_number := 'PAY-' || TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD-HH24MISS');
        END;
    END IF;

    -- Note: Journal entry and bank transaction creation is now handled by
    -- trg_payment_journal_entry trigger (AFTER INSERT)
    -- This trigger only handles payment number generation

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    -- Don't block payment creation
    RAISE WARNING 'handle_payment_financial_integration error: %', SQLERRM;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_invoice_on_payment_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payment_id uuid;
  v_invoice_id uuid;
  v_contract_id uuid;
  v_invoice_ids uuid[] := ARRAY[]::uuid[];
  v_contract_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_payment_id := NEW.id;
    IF NEW.invoice_id IS NOT NULL THEN v_invoice_ids := array_append(v_invoice_ids, NEW.invoice_id); END IF;
    IF NEW.contract_id IS NOT NULL THEN v_contract_ids := array_append(v_contract_ids, NEW.contract_id); END IF;
  END IF;
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_payment_id := OLD.id;
    IF OLD.invoice_id IS NOT NULL THEN v_invoice_ids := array_append(v_invoice_ids, OLD.invoice_id); END IF;
    IF OLD.contract_id IS NOT NULL THEN v_contract_ids := array_append(v_contract_ids, OLD.contract_id); END IF;
  END IF;

  SELECT
    v_invoice_ids || COALESCE(array_agg(DISTINCT allocation.target_id), ARRAY[]::uuid[])
  INTO v_invoice_ids
  FROM public.payment_allocations allocation
  WHERE allocation.payment_id = v_payment_id
    AND allocation.allocation_type = 'invoice';

  FOR v_invoice_id IN
    SELECT DISTINCT candidate_id
    FROM unnest(v_invoice_ids) candidate(candidate_id)
    WHERE candidate_id IS NOT NULL
  LOOP
    PERFORM public.recalculate_invoice_financial_state(v_invoice_id);
    SELECT invoice.contract_id INTO v_contract_id
    FROM public.invoices invoice WHERE invoice.id = v_invoice_id;
    IF v_contract_id IS NOT NULL THEN
      v_contract_ids := array_append(v_contract_ids, v_contract_id);
    END IF;
  END LOOP;

  FOR v_contract_id IN
    SELECT DISTINCT candidate_id
    FROM unnest(v_contract_ids) candidate(candidate_id)
    WHERE candidate_id IS NOT NULL
  LOOP
    PERFORM public.recalculate_contract_financial_state(v_contract_id);
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

