CREATE OR REPLACE FUNCTION public.sync_contract_last_payment_date_from_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_contract_id uuid;
  v_old_company_id uuid;
  v_new_contract_id uuid;
  v_new_company_id uuid;
  v_contract_id uuid;
  v_company_id uuid;
  v_last_date date;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_old_company_id := OLD.company_id;
    v_old_contract_id := OLD.contract_id;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_new_company_id := NEW.company_id;
    v_new_contract_id := NEW.contract_id;
  END IF;

  FOR v_company_id, v_contract_id IN
    SELECT pair.company_id, pair.contract_id
    FROM (
      VALUES
        (v_old_company_id, v_old_contract_id),
        (v_new_company_id, v_new_contract_id)
    ) AS pair(company_id, contract_id)
    WHERE pair.company_id IS NOT NULL
      AND pair.contract_id IS NOT NULL
    GROUP BY pair.company_id, pair.contract_id
  LOOP
    SELECT max(payment.payment_date)
    INTO v_last_date
    FROM public.payments payment
    WHERE payment.company_id = v_company_id
      AND payment.contract_id = v_contract_id
      AND lower(COALESCE(payment.payment_status, '')) = 'completed'
      AND lower(COALESCE(payment.transaction_type::text, 'receipt')) = 'receipt';

    UPDATE public.contracts contract
    SET last_payment_date = v_last_date,
        updated_at = now()
    WHERE contract.id = v_contract_id
      AND contract.company_id = v_company_id
      AND contract.last_payment_date IS DISTINCT FROM v_last_date;
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_payment_invoice_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_invoice_company_id uuid;
  v_invoice_contract_id uuid;
  v_invoice_customer_id uuid;
BEGIN
  IF NEW.invoice_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT invoice.company_id, invoice.contract_id, invoice.customer_id
  INTO v_invoice_company_id, v_invoice_contract_id, v_invoice_customer_id
  FROM public.invoices invoice
  WHERE invoice.id = NEW.invoice_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment invoice does not exist (%)', NEW.invoice_id
      USING ERRCODE = '23503';
  END IF;

  IF NEW.company_id IS DISTINCT FROM v_invoice_company_id THEN
    RAISE EXCEPTION 'Payment and invoice must belong to the same company'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.contract_id IS NOT NULL
     AND v_invoice_contract_id IS NOT NULL
     AND NEW.contract_id IS DISTINCT FROM v_invoice_contract_id THEN
    RAISE EXCEPTION 'Payment contract does not match invoice contract'
      USING ERRCODE = '23514';
  END IF;

  IF NEW.customer_id IS NOT NULL
     AND v_invoice_customer_id IS NOT NULL
     AND NEW.customer_id IS DISTINCT FROM v_invoice_customer_id THEN
    RAISE EXCEPTION 'Payment customer does not match invoice customer'
      USING ERRCODE = '23514';
  END IF;

  NEW.contract_id := COALESCE(NEW.contract_id, v_invoice_contract_id);
  NEW.customer_id := COALESCE(NEW.customer_id, v_invoice_customer_id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.financial_audit_trigger_fn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action text;
  v_company_id uuid;
  v_resource_id uuid;
  v_resource_type text;
  v_details jsonb;
  v_severity text := 'low';
  v_status text := 'success';
  v_old_row jsonb := NULL;
  v_new_row jsonb := NULL;
  v_user_id uuid := auth.uid();
BEGIN
  v_resource_type := TG_TABLE_NAME;

  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    v_old_row := to_jsonb(OLD);
  END IF;

  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    v_new_row := to_jsonb(NEW);
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_action := v_resource_type || '_created';
    v_company_id := NEW.company_id;
    v_resource_id := NEW.id;
    v_details := jsonb_build_object('new_values', v_new_row);
    IF TG_TABLE_NAME = 'payments' THEN
      v_severity := 'medium';
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := v_resource_type || '_updated';
    v_company_id := NEW.company_id;
    v_resource_id := NEW.id;
    v_details := jsonb_build_object(
      'old_values', v_old_row,
      'new_values', v_new_row,
      'changed_fields', (
        SELECT jsonb_object_agg(key, value)
        FROM jsonb_each(v_new_row) AS n
        WHERE n.value IS DISTINCT FROM (v_old_row -> n.key)
      )
    );

    IF TG_TABLE_NAME = 'payments'
       AND (v_old_row ->> 'payment_status') IS DISTINCT FROM (v_new_row ->> 'payment_status')
    THEN
      v_severity := 'high';
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    v_action := v_resource_type || '_deleted';
    v_company_id := OLD.company_id;
    v_resource_id := OLD.id;
    v_details := jsonb_build_object('old_values', v_old_row);
    v_severity := 'critical';
  END IF;

  v_user_id := COALESCE(
    NULLIF(v_new_row ->> 'created_by', '')::uuid,
    NULLIF(v_old_row ->> 'created_by', '')::uuid,
    auth.uid()
  );

  INSERT INTO public.audit_logs (
    action,
    severity,
    company_id,
    resource_type,
    resource_id,
    old_values,
    new_values,
    metadata,
    status,
    user_id
  )
  VALUES (
    v_action,
    v_severity,
    v_company_id,
    v_resource_type,
    v_resource_id,
    CASE WHEN v_details ? 'old_values' THEN v_details -> 'old_values' ELSE NULL END,
    CASE WHEN v_details ? 'new_values' THEN v_details -> 'new_values' ELSE NULL END,
    CASE WHEN v_details ? 'changed_fields' THEN v_details -> 'changed_fields' ELSE NULL END,
    v_status,
    v_user_id
  );

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_payment_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy_exists BOOLEAN;
  v_has_approval BOOLEAN;
BEGIN
  IF NEW.payment_status <> 'completed' OR OLD.payment_status = 'completed' THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.financial_approval_policies
    WHERE company_id = NEW.company_id
      AND action = 'payment_create'
      AND is_active = true
      AND NEW.amount >= min_amount
      AND (max_amount IS NULL OR NEW.amount <= max_amount)
  ) INTO v_policy_exists;

  IF NOT v_policy_exists THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.financial_approval_requests
    WHERE source_table = 'payments'
      AND source_id = NEW.id
      AND action = 'payment_create'
      AND status = 'approved'
  ) INTO v_has_approval;

  IF NOT v_has_approval THEN
    RAISE EXCEPTION 'Payment amount % exceeds approval threshold. An approved financial approval request is required before completion.', NEW.amount;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_payment_with_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_remaining_amount DECIMAL(12,2);
  v_amount_to_apply DECIMAL(12,2);
  v_new_paid_amount DECIMAL(12,2);
  v_new_balance DECIMAL(12,2);
  v_new_status TEXT;
BEGIN
  -- Only process completed payments
  IF NEW.payment_status != 'completed' THEN
    RETURN NEW;
  END IF;

  -- Skip if payment is already linked to an invoice
  IF NEW.invoice_id IS NOT NULL THEN
    -- Update only the linked invoice
    SELECT * INTO v_invoice FROM public.invoices WHERE id = NEW.invoice_id;
    IF FOUND THEN
      v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + NEW.amount;
      v_new_balance := v_invoice.total_amount - v_new_paid_amount;
      v_new_status := CASE WHEN v_new_balance <= 0 THEN 'paid' WHEN v_new_paid_amount > 0 THEN 'partial' ELSE 'unpaid' END;

      UPDATE public.invoices SET
        paid_amount = v_new_paid_amount,
        balance_due = GREATEST(0, v_new_balance),
        payment_status = v_new_status
      WHERE id = NEW.invoice_id;
    END IF;
    RETURN NEW;
  END IF;

  -- If no invoice linked, find and update unpaid invoices for this contract
  IF NEW.contract_id IS NOT NULL THEN
    v_remaining_amount := NEW.amount;

    FOR v_invoice IN 
      SELECT id, total_amount, COALESCE(paid_amount, 0) as paid_amount
      FROM public.invoices 
      WHERE contract_id = NEW.contract_id 
        AND payment_status IN ('unpaid', 'partial')
      ORDER BY due_date ASC
    LOOP
      EXIT WHEN v_remaining_amount <= 0;

      v_amount_to_apply := LEAST(v_remaining_amount, v_invoice.total_amount - v_invoice.paid_amount);

      IF v_amount_to_apply > 0 THEN
        v_new_paid_amount := v_invoice.paid_amount + v_amount_to_apply;
        v_new_balance := v_invoice.total_amount - v_new_paid_amount;
        v_new_status := CASE WHEN v_new_balance <= 0 THEN 'paid' WHEN v_new_paid_amount > 0 THEN 'partial' ELSE 'unpaid' END;

        UPDATE public.invoices SET
          paid_amount = v_new_paid_amount,
          balance_due = GREATEST(0, v_new_balance),
          payment_status = v_new_status
        WHERE id = v_invoice.id;

        v_remaining_amount := v_remaining_amount - v_amount_to_apply;

        -- Link payment to first invoice it was applied to
        IF NEW.invoice_id IS NULL THEN
          NEW.invoice_id := v_invoice.id;
        END IF;
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_and_calculate_late_fee_on_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_days_overdue integer;
  v_fee_amount numeric := 0;
  v_late_fee_id uuid;
  v_existing_fee uuid;
  v_rule RECORD;
  v_payment_date date;
  v_daily_rate numeric := 0;
  v_max_percentage numeric := 100;
  v_daily_amount numeric := 0;
  v_max_amount numeric := 100000;
  v_tier jsonb;
  v_min_days integer;
  v_max_days integer;
BEGIN
  IF NEW.invoice_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT
    i.id,
    i.company_id,
    i.invoice_number,
    i.customer_id,
    i.contract_id,
    i.due_date,
    i.total_amount,
    i.invoice_type,
    i.payment_status,
    i.status
  INTO v_invoice
  FROM public.invoices i
  WHERE i.id = NEW.invoice_id;

  IF NOT FOUND OR v_invoice.due_date IS NULL THEN
    RETURN NEW;
  END IF;

  v_payment_date := NEW.payment_date::date;
  IF v_payment_date <= v_invoice.due_date THEN
    RETURN NEW;
  END IF;

  v_days_overdue := v_payment_date - v_invoice.due_date;

  SELECT id
    INTO v_existing_fee
  FROM public.late_fees
  WHERE invoice_id = NEW.invoice_id
    AND status IN ('pending', 'applied')
    AND days_overdue = v_days_overdue
  LIMIT 1;

  IF v_existing_fee IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT *
    INTO v_rule
  FROM public.late_fee_rules
  WHERE company_id = NEW.company_id
    AND is_enabled = true
    AND COALESCE(minimum_overdue_days, 1) <= v_days_overdue
  ORDER BY priority DESC, created_at ASC
  LIMIT 1;

  IF NOT FOUND OR v_days_overdue <= v_rule.grace_period_days THEN
    RETURN NEW;
  END IF;

  IF v_rule.rule_type = 'percentage' THEN
    v_daily_rate := COALESCE(NULLIF(v_rule.fee_structure->>'dailyRate', '')::numeric, 0);
    v_max_percentage := COALESCE(NULLIF(v_rule.fee_structure->>'maxPercentage', '')::numeric, 100);
    v_fee_amount := v_invoice.total_amount * (v_daily_rate / 100) * v_days_overdue;
    v_fee_amount := LEAST(v_fee_amount, v_invoice.total_amount * (v_max_percentage / 100));
  ELSIF v_rule.rule_type = 'fixed' THEN
    v_daily_amount := COALESCE(NULLIF(v_rule.fee_structure->>'dailyAmount', '')::numeric, 0);
    v_max_amount := COALESCE(NULLIF(v_rule.fee_structure->>'maxAmount', '')::numeric, 100000);
    v_fee_amount := LEAST(v_daily_amount * v_days_overdue, v_max_amount);
  ELSIF v_rule.rule_type = 'tiered' THEN
    FOR v_tier IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_rule.fee_structure->'tiers', '[]'::jsonb))
    LOOP
      v_min_days := COALESCE(NULLIF(v_tier->>'minDays', '')::integer, 0);
      v_max_days := COALESCE(NULLIF(v_tier->>'maxDays', '')::integer, 2147483647);
      IF v_days_overdue BETWEEN v_min_days AND v_max_days THEN
        v_daily_rate := COALESCE(NULLIF(v_tier->>'dailyRate', '')::numeric, 0);
        v_max_amount := COALESCE(NULLIF(v_tier->>'maxAmount', '')::numeric, 100000);
        v_fee_amount := LEAST(v_invoice.total_amount * (v_daily_rate / 100) * v_days_overdue, v_max_amount);
        EXIT;
      END IF;
    END LOOP;
  END IF;

  IF v_fee_amount <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.late_fees (
    company_id,
    invoice_id,
    contract_id,
    late_fee_rule_id,
    original_amount,
    days_overdue,
    fee_amount,
    fee_type,
    status,
    created_at
  )
  VALUES (
    NEW.company_id,
    NEW.invoice_id,
    v_invoice.contract_id,
    v_rule.id,
    v_invoice.total_amount,
    v_days_overdue,
    v_fee_amount,
    COALESCE(v_rule.rule_type, 'fixed'),
    'pending',
    now()
  )
  RETURNING id INTO v_late_fee_id;

  INSERT INTO public.late_fee_history (late_fee_id, action, notes)
  VALUES (
    v_late_fee_id,
    'created',
    format(
      'Auto-generated on payment registration. Payment date: %s, Due date: %s, Days overdue: %s',
      v_payment_date,
      v_invoice.due_date,
      v_days_overdue
    )
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_payment_overpayment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_invoice RECORD;
  v_total_paid DECIMAL(12,2);
  v_new_total DECIMAL(12,2);
BEGIN
  IF NEW.invoice_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT total_amount, paid_amount INTO v_invoice
  FROM invoices WHERE id = NEW.invoice_id;

  IF v_invoice IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(SUM(amount), 0) INTO v_total_paid
  FROM payments
  WHERE invoice_id = NEW.invoice_id 
    AND payment_status = 'completed'
    AND id != COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::UUID);

  v_new_total := v_total_paid + NEW.amount;

  IF v_new_total > v_invoice.total_amount THEN
    NEW.notes := COALESCE(NEW.notes, '') || ' [تحذير: دفعة تتجاوز قيمة الفاتورة بـ ' || 
                 (v_new_total - v_invoice.total_amount)::TEXT || ' ر.ق.]';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_invoice_on_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.invoice_id IS NOT NULL THEN
    PERFORM public.recalculate_invoice_financial_state(NEW.invoice_id);
  END IF;

  IF TG_OP = 'UPDATE'
     AND OLD.invoice_id IS NOT NULL
     AND OLD.invoice_id IS DISTINCT FROM NEW.invoice_id
  THEN
    PERFORM public.recalculate_invoice_financial_state(OLD.invoice_id);
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_receipt_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
    year_suffix TEXT;
    seq_num TEXT;
BEGIN
    IF NEW.receipt_number IS NULL THEN
        year_suffix := TO_CHAR(NEW.payment_date, 'YY');
        seq_num := LPAD(nextval('public.receipt_number_seq')::TEXT, 6, '0');
        NEW.receipt_number := 'RCP-' || year_suffix || '-' || seq_num;
        NEW.fiscal_year := EXTRACT(YEAR FROM NEW.payment_date);
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_rental_payment_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  -- Calculate pending balance
  NEW.pending_balance := GREATEST(0, NEW.amount_due - NEW.total_paid);

  -- Determine payment status
  IF NEW.total_paid >= NEW.amount_due THEN
    NEW.payment_status := 'paid';
  ELSIF NEW.total_paid > 0 THEN
    NEW.payment_status := 'partial';
  ELSE
    NEW.payment_status := 'pending';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_rental_receipt_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
